INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das Interface Segregation Principle nur für große Interfaces?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Interfaces profitieren"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Interface Segregation Principle?', 3, '[{"text": "Schlanke Schnittstellen", "correct": true, "because": "Nur nötige Methoden"}, {"text": "Code schneller machen", "correct": false, "because": "Kein Performance-Fokus"}, {"text": "Weniger Klassen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Interface Segregation Principle?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Klassen wählen relevante Interfaces"}, {"text": "Wartbarkeit", "correct": true, "because": "Kleine Änderungen isolieren"}, {"text": "Schnellere Builds", "correct": false, "because": "Kein Build-Fokus"}, {"text": "Weniger Speicher", "correct": false, "because": "Unabhängig davon"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ISP trennt Interfaces nach Zweck. b) Es erfordert immer mehr Klassen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klassenanzahl nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Interface Segregation Principle?', 4, '[{"text": "Spezifität", "correct": false, "because": "Kern des Prinzips"}, {"text": "Relevanz", "correct": false, "because": "Methoden müssen zweckmäßig sein"}, {"text": "UI-Animationen", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ISP überladene Interfaces erlaubt?', 2, '[{"text": "Nein", "correct": true, "because": "Vermeidet unnötige Methoden"}, {"text": "Ja", "correct": false, "because": "Widerspricht ISP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel folgt dem Interface Segregation Principle?', 3, '[{"text": "Getrennte Interfaces für Lesen und Schreiben", "correct": true, "because": "Spezifische Zwecke"}, {"text": "Ein Interface mit allen Methoden", "correct": false, "because": "Überladen"}, {"text": "Interface mit UI-Logik", "correct": false, "because": "Nicht zweckmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördert das Interface Segregation Principle?', 5, '[{"text": "Lose Kopplung", "correct": true, "because": "Klassen wählen nur Nötiges"}, {"text": "Klarheit", "correct": true, "because": "Spezifische Schnittstellen"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Kein Performance-Ziel"}, {"text": "Weniger Zeilen", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ISP reduziert Abhängigkeiten. b) Es macht Tests überflüssig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests bleiben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Interface Segregation Principle?', 4, '[{"text": "Spezifische Interfaces", "correct": false, "because": "Kern des ISP"}, {"text": "Relevante Methoden", "correct": false, "because": "Zweckmäßigkeit essenziell"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ISP ohne mehrere Interfaces möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Trennung ist zentral"}, {"text": "Ja", "correct": false, "because": "Ein Interface widerspricht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme löst das Interface Segregation Principle?', 4, '[{"text": "Überladene Schnittstellen", "correct": true, "because": "Nur nötige Methoden"}, {"text": "Zwangsimplementierung", "correct": true, "because": "Klassen frei wählen"}, {"text": "Langsame Ausführung", "correct": false, "because": "Kein Performance-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ISP nur für Teams gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Solo nützlich"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Interface Segregation Principle?', 3, '[{"text": "Zweckmäßige Trennung", "correct": true, "because": "Relevanz der Methoden"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Viele Methoden", "correct": false, "because": "Widerspricht ISP"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ISP fördert Flexibilität. b) Es garantiert kürzeren Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kürze nicht Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das Interface Segregation Principle?', 5, '[{"text": "Mehr Interfaces", "correct": true, "because": "Trennung erhöht Anzahl"}, {"text": "Höherer Designaufwand", "correct": true, "because": "Planung nötig"}, {"text": "Langsamere Tests", "correct": false, "because": "Kein Test-Effekt"}, {"text": "Hoher Speicher", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Interface Segregation Principle unwichtig?', 3, '[{"text": "Spezifität", "correct": false, "because": "Kernprinzip"}, {"text": "Relevanz", "correct": false, "because": "Methoden zweckmäßig"}, {"text": "Farbschema", "correct": true, "because": "Kein Code-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht ISP die Anzahl der Klassen?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Interfaces steigen"}, {"text": "Ja", "correct": false, "because": "Klassen unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ISP Tests erleichtert?', 2, '[{"text": "Ja", "correct": true, "because": "Kleinere Interfaces prüfbar"}, {"text": "Nein", "correct": false, "because": "Testbarkeit steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ergänzt das Interface Segregation Principle?', 4, '[{"text": "Single Responsibility", "correct": true, "because": "Fokus auf eine Aufgabe"}, {"text": "KISS", "correct": false, "because": "Allgemeiner Ansatz"}, {"text": "YAGNI", "correct": false, "because": "Anderer Fokus"}]');
